import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';

test('exportCsv returns header for empty invoices', () => {
  const result = exportCsv([]);
  assert.equal(result, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv includes header line', () => {
  const result = exportCsv([]);
  assert(result.startsWith('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n'));
});

test('exportCsv with single invoice', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 21 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert.equal(lines.length, 3);
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert(lines[1].includes('INV-2026-0001'));
  assert(lines[1].includes('C-001'));
  assert(lines[1].includes('2026-10-07'));
  assert(lines[1].includes('2026-11-06'));
  assert(lines[1].includes('issued'));
});

test('exportCsv formats amounts correctly', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 21 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[5], '100.00');
  assert.equal(fields[6], '0.00');
  assert.equal(fields[7], '21.00');
  assert.equal(fields[8], '121.00');
  assert.equal(fields[9], '121.00');
});

test('exportCsv uses customer name not ID', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert(lines[1].includes('Acme Inc'));
  assert(!lines[1].includes('C-001'));
});

test('exportCsv with multiple invoices', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0002',
      customerId: 'C-003',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'paid',
      lines: [{ qty: 2, unitPrice: 5000, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert.equal(lines.length, 4);
  assert(lines[1].includes('INV-2026-0001'));
  assert(lines[2].includes('INV-2026-0002'));
});

test('exportCsv with discount', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 10, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[5], '100.00');
  assert.equal(fields[6], '10.00');
  assert.equal(fields[8], '90.00');
});

test('exportCsv lines end with newline', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  assert(result.endsWith('\n'));
});

test('exportCsv escapes commas in customer name', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-010',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert(lines[1].includes('"'));
});

test('exportCsv escapes quotes in customer name', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[1], 'Acme Inc');
});

test('exportCsv with multiple lines on invoice', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [
        { qty: 1, unitPrice: 8500, vatRate: 21 },
        { qty: 2, unitPrice: 9500, vatRate: 21 },
      ],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  const subtotal = 8500 + 19000;
  const vat = Math.round(subtotal * 21 / 100);
  assert.equal(fields[5], (subtotal / 100).toFixed(2));
  assert.equal(fields[7], (vat / 100).toFixed(2));
});

test('exportCsv with draft invoice', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'draft',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert(lines[1].includes('draft'));
});

test('exportCsv with zero amounts', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 100, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[8], '0.00');
});

test('exportCsv with large amounts', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 999999, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[5], '9999.99');
});

test('exportCsv with small amounts', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 1, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[5], '0.01');
});

test('exportCsv amounts have exactly 2 decimals', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 12345, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.match(fields[5], /^\d+\.\d{2}$/);
});

test('exportCsv preserves invoice order', () => {
  const invoices = [
    {
      number: 'INV-2026-0003',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0002',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert(lines[1].includes('INV-2026-0003'));
  assert(lines[2].includes('INV-2026-0001'));
  assert(lines[3].includes('INV-2026-0002'));
});

test('exportCsv handles missing number', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'draft',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[0], '');
});

test('exportCsv handles missing dueDate', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      status: 'draft',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[3], '');
});

test('exportCsv with different statuses', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0002',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'partially_paid',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0003',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'paid',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert(lines[1].includes('issued'));
  assert(lines[2].includes('partially_paid'));
  assert(lines[3].includes('paid'));
});

test('exportCsv due field equals total field', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 21 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[8], fields[9]);
});

test('exportCsv with voucher', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
      voucher: { code: 'SAVE10', amount: 2000 },
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[8], '80.00');
});

test('exportCsv complex invoice with all features', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [
        { qty: 2, unitPrice: 8500, discountPercent: 5, vatRate: 21 },
        { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 9 },
      ],
      voucher: { code: 'SAVE5', amount: 500 },
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert(lines[1].includes('INV-2026-0001'));
  assert(lines[1].includes('Acme Inc'));
  assert(lines[1].includes('2026-10-07'));
  assert(lines[1].includes('2026-11-06'));
  assert(lines[1].includes('issued'));
});

test('exportCsv CSV format is valid', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert.equal(lines[0].split(',').length, 10);
  assert.equal(lines[1].split(',').length, 10);
});

test('exportCsv preserves input invoices', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const original = JSON.parse(JSON.stringify(invoices));
  exportCsv(invoices);
  assert.deepEqual(invoices, original);
});

